import { gql } from "~/gql";

// Operation names are global across erxes; keep the plugin prefix. gql() is
// generated by codegen — write documents as static strings (no `${}`), and
// let Apollo hooks infer their types from the document.
export const STATUS_QUERY = gql(`
  query subedeiStatus {
    subedeiStatus {
      plugin
      version
      subdomain
      userId
      userEmail
      school
      llmModel
      llmReachable
      tts
      stt
      sms
      erxesSync
    }
  }
`);

export const TODAY_QUERY = gql(`
  query subedeiToday {
    subedeiToday {
      date
      classroomName
      pickupTime
      counts {
        total
        present
        absent
        excused
        late
        unknown
        pickedUp
        waiting
        contacting
        coming
        unreachable
      }
      students {
        studentId
        firstName
        lastName
        attendance
        attendanceNote
        pickup {
          status
          etaMinutes
          expectedAt
          pickupPerson
          note
          pickedUpAt
          pickedUpBy
        }
        guardians {
          _id
          name
          relation
          phone
        }
        lastCall {
          _id
          status
          purpose
          ringingAt
          transcript
          intent {
            outcome
            summary
            engine
          }
        }
      }
    }
  }
`);

export const CALLS_QUERY = gql(`
  query subedeiCalls($limit: Int) {
    subedeiCalls(limit: $limit) {
      _id
      purpose
      status
      attempt
      ringingAt
      transcript
      studentId
      guardian {
        _id
        name
        relation
        phone
      }
      intent {
        outcome
        summary
        engine
        model
      }
    }
  }
`);

export const MARK_ATTENDANCE = gql(`
  mutation subedeiMarkAttendance($studentId: String!, $status: String!) {
    subedeiMarkAttendance(studentId: $studentId, status: $status)
  }
`);

export const MARK_PICKED_UP = gql(`
  mutation subedeiMarkPickedUp($studentId: String!, $by: String) {
    subedeiMarkPickedUp(studentId: $studentId, by: $by)
  }
`);

export const CALL_GUARDIANS = gql(`
  mutation subedeiCallGuardians($studentId: String!, $purpose: String!) {
    subedeiCallGuardians(studentId: $studentId, purpose: $purpose)
  }
`);

export const CHECK_LATE_PICKUPS = gql(`
  mutation subedeiCheckLatePickups {
    subedeiCheckLatePickups
  }
`);
